import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import java.util.TreeMap;
import java.util.stream.Collectors;

public class Analytics {

    public static TreeMap<String, Double> averageSalaryByDept(List<Employee> staff) {
        return staff.stream().collect(Collectors.groupingBy(
                Employee::getDept,
                TreeMap::new,
                Collectors.averagingDouble(Employee::getSalary)));
    }

    public static List<String> namesSortedBySalaryDesc(List<Employee> staff) {
        return staff.stream()
                .sorted(Comparator.comparingDouble(Employee::getSalary).reversed()
                        .thenComparing(Employee::getName))
                .map(Employee::getName)
                .collect(Collectors.toList());
    }

    public static Optional<Employee> highestPaidIn(List<Employee> staff, String dept) {
        return staff.stream()
                .filter(e -> e.getDept().equals(dept))
                .max(Comparator.comparingDouble(Employee::getSalary));
    }
}

