import java.util.Arrays;
import java.util.List;
import java.util.Optional;
import java.util.TreeMap;

public class AnalyticsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Double round2(Double value) {
        if (value == null) {
            return null;
        }
        return Math.round(value * 100.0) / 100.0;
    }

    public static void main(String[] args) {
        List<Employee> staff = Arrays.asList(
                new Employee("Ada", "eng", 120000.0),
                new Employee("Bo", "eng", 100000.0),
                new Employee("Cy", "ops", 90000.0),
                new Employee("Dee", "eng", 140000.0),
                new Employee("Eve", "sales", 100000.0),
                new Employee("Al", "sales", 100000.0));

        TreeMap<String, Double> averages = Analytics.averageSalaryByDept(staff);
        check("three departments in the map", 3, averages == null ? -1 : averages.size());
        if (averages != null) {
            check("average salary in eng", 120000.0, round2(averages.get("eng")));
            check("average salary in ops", 90000.0, round2(averages.get("ops")));
            check("average salary in sales", 100000.0, round2(averages.get("sales")));
            check("department keys come out sorted", "[eng, ops, sales]", String.valueOf(averages.keySet()));
            check("a department nobody works in", null, averages.get("legal"));
        } else {
            System.out.println("FAIL  averageSalaryByDept returned null");
            failures += 5;
        }
        check("averages of an empty staff list", 0,
                Analytics.averageSalaryByDept(Arrays.asList()).size());

        check("names by salary, ties broken by name",
                "[Dee, Ada, Al, Bo, Eve, Cy]", String.valueOf(Analytics.namesSortedBySalaryDesc(staff)));
        check("names of an empty staff list", "[]",
                String.valueOf(Analytics.namesSortedBySalaryDesc(Arrays.asList())));

        Optional<Employee> topEng = Analytics.highestPaidIn(staff, "eng");
        check("highest paid in eng is present", true, topEng != null && topEng.isPresent());
        check("highest paid in eng", "Dee/eng",
                topEng == null || !topEng.isPresent() ? null : String.valueOf(topEng.get()));
        Optional<Employee> topOps = Analytics.highestPaidIn(staff, "ops");
        check("highest paid in a one-person department", "Cy/ops",
                topOps == null || !topOps.isPresent() ? null : String.valueOf(topOps.get()));
        Optional<Employee> topLegal = Analytics.highestPaidIn(staff, "legal");
        check("no employee in that department", true, topLegal != null && !topLegal.isPresent());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

